// Python emitter: model -> { models, client } source strings. Pure. Targets Python 3.9+, stdlib only.

import { refKey, oneLine } from "./model.mjs";
import { PY_KEYWORDS } from "./names.mjs";

export const PY_BANNER =
  "# DO NOT EDIT. Generated by sdk/generate.mjs from docs/api/openapi.json.\n" +
  "# Regenerate with: node sdk/generate.mjs\n";

function refName(ref, ctx) {
  const key = refKey(ref);
  const name = ctx.typeNames.get(key);
  if (!name) throw new Error(`$ref to unknown schema: ${ref}`);
  const full = ctx.prefix + name;
  return ctx.quoteRefs ? JSON.stringify(full) : full;
}

function pyLiteral(v) {
  if (typeof v === "string") return JSON.stringify(v);
  if (typeof v === "boolean") return v ? "True" : "False";
  if (v === null) return "None";
  return String(v);
}

function isEmptySchema(s) {
  return s == null || s === true || (typeof s === "object" && Object.keys(s).length === 0);
}

/**
 * Python type expression for a JSON Schema.
 * `ctx = { typeNames: Map, prefix: "" | "m.", quoteRefs: boolean }`; quoteRefs writes refs as string
 * forward references, which is needed wherever the expression is evaluated at import time.
 */
export function pyType(s, ctx) {
  if (isEmptySchema(s)) return "Any";
  if (s.$ref) return refName(s.$ref, ctx);
  if (Array.isArray(s.enum)) {
    return s.enum.length ? `Literal[${s.enum.map(pyLiteral).join(", ")}]` : "Any";
  }
  const alt = s.oneOf ?? s.anyOf;
  if (Array.isArray(alt) && alt.length) {
    return `Union[${alt.map((x) => pyType(x, ctx)).join(", ")}]`;
  }
  if (Array.isArray(s.allOf) && s.allOf.length) return "Dict[str, Any]";
  const type = Array.isArray(s.type) ? s.type.find((t) => t !== "null") : s.type;
  switch (type) {
    case "string":
      return s.format === "binary" ? "bytes" : "str";
    case "integer":
      return "int";
    case "number":
      return "float";
    case "boolean":
      return "bool";
    case "null":
      return "None";
    case "array":
      return `List[${pyType(s.items ?? {}, ctx)}]`;
    case "object":
      if (s.additionalProperties && s.additionalProperties !== true && !s.properties) {
        return `Dict[str, ${pyType(s.additionalProperties, ctx)}]`;
      }
      return "Dict[str, Any]";
    default:
      return "Any";
  }
}

function isRequired(schema, key) {
  const required = Array.isArray(schema.required) && schema.required.includes(key);
  const prop = schema.properties[key];
  const hasDefault = prop && typeof prop === "object" && "default" in prop;
  return required && !hasDefault;
}

function isPyIdent(name) {
  return /^[A-Za-z_][A-Za-z0-9_]*$/.test(name) && !PY_KEYWORDS.has(name);
}

/** models.py: Literal aliases and TypedDicts for every component schema. */
export function emitModels(model) {
  const aliasCtx = { typeNames: model.typeNames, prefix: "", quoteRefs: true };
  const fieldCtx = { typeNames: model.typeNames, prefix: "", quoteRefs: false };
  let out = `${PY_BANNER}\nfrom __future__ import annotations\n\n`;
  out += "from typing import Any, Dict, List, Literal, Optional, TypedDict, Union  # noqa: F401\n\n";
  const aliases = [];
  const dicts = [];
  for (const { name, schema } of model.schemas) {
    const props = schema && schema.properties ? Object.keys(schema.properties) : [];
    if (props.length > 0) dicts.push({ name, schema, props });
    else aliases.push({ name, schema });
  }
  for (const { name, schema } of aliases) {
    if (schema && schema.description) out += `# ${oneLine(schema.description)}\n`;
    out += `${name} = ${pyType(schema, aliasCtx)}\n\n`;
  }
  for (const { name, schema, props } of dicts) out += emitTypedDict(name, schema, props, fieldCtx);
  return out.replace(/\n+$/, "\n");
}

function emitTypedDict(name, schema, props, ctx) {
  const doc = schema.description ? `    """${oneLine(schema.description).replace(/"""/g, "'''").replace(/\\/g, "/").replace(/"$/, "'")}"""\n\n` : "";
  if (!props.every(isPyIdent)) {
    // Keys that are not valid Python identifiers need the functional TypedDict form (all keys optional).
    const entries = props.map((k) => `${JSON.stringify(k)}: ${JSON.stringify(pyType(schema.properties[k], ctx))}`);
    return `${name} = TypedDict(${JSON.stringify(name)}, {${entries.join(", ")}}, total=False)\n\n\n`;
  }
  const required = props.filter((k) => isRequired(schema, k));
  const optional = props.filter((k) => !isRequired(schema, k));
  const line = (k) => `    ${k}: ${pyType(schema.properties[k], ctx)}\n`;
  let out = "";
  if (required.length && optional.length) {
    out += `class _${name}Required(TypedDict):\n${required.map(line).join("")}\n\n`;
    out += `class ${name}(_${name}Required, total=False):\n${doc}${optional.map(line).join("")}\n\n`;
  } else if (required.length) {
    out += `class ${name}(TypedDict):\n${doc}${required.map(line).join("")}\n\n`;
  } else {
    out += `class ${name}(TypedDict, total=False):\n${doc}${optional.map(line).join("")}\n\n`;
  }
  return out;
}

function pathExpr(op) {
  if (op.pathParams.length === 0) return JSON.stringify(op.path);
  let out = op.path.replace(/\\/g, "\\\\").replace(/"/g, '\\"').replace(/\{/g, "{{").replace(/\}/g, "}}");
  for (const p of op.pathParams) {
    out = out.split(`{{${p.name}}}`).join(`{quote_path(${p.py})}`);
  }
  return `f"${out}"`;
}

function bodyType(body, ctx) {
  if (body.kind === "json") return pyType(body.schema, ctx);
  if (body.kind === "multipart") return "Dict[str, Any]";
  if (body.kind === "text") return "str";
  return "bytes";
}

function returnType(op, ctx) {
  switch (op.response.kind) {
    case "sse":
      return "Iterator[str]";
    case "void":
      return "None";
    case "text":
      return "str";
    case "blob":
      return "bytes";
    default:
      return pyType(op.response.schema, ctx);
  }
}

function emitOperation(op, ctx) {
  const positional = op.pathParams.map((p) => `${p.py}: ${pyType(p.schema, ctx)}`);
  if (op.body) {
    const t = bodyType(op.body, ctx);
    positional.push(op.body.required ? `body: ${t}` : `body: Optional[${t}] = None`);
  }
  const keyword = [];
  for (const p of [...op.queryParams, ...op.headerParams]) {
    const t = pyType(p.schema, ctx);
    keyword.push(p.required ? `${p.py}: ${t}` : `${p.py}: Optional[${t}] = None`);
  }
  const params = ["self", ...positional];
  if (keyword.length) params.push("*", ...keyword);

  const call = [JSON.stringify(op.verb.toUpperCase()), pathExpr(op)];
  if (op.queryParams.length) {
    call.push(`query={${op.queryParams.map((p) => `${JSON.stringify(p.name)}: ${p.py}`).join(", ")}}`);
  }
  if (op.headerParams.length) {
    call.push(`headers={${op.headerParams.map((p) => `${JSON.stringify(p.name)}: ${p.py}`).join(", ")}}`);
  }
  if (op.body) {
    call.push("body=body");
    if (op.body.kind !== "json") call.push(`body_type=${JSON.stringify(op.body.kind)}`);
    if (op.body.kind === "text" || op.body.kind === "raw") call.push(`content_type=${JSON.stringify(op.body.mediaType)}`);
  }
  const kind = op.response.kind;
  if (kind === "void" || kind === "text" || kind === "blob") call.push(`response=${JSON.stringify(kind)}`);

  const method = kind === "sse" ? "stream" : "request";
  const title = (oneLine(op.summary) || op.id).replace(/"""/g, "'''").replace(/\\/g, "/");
  const verbPath = `${op.verb.toUpperCase()} ${op.path}`.replace(/\\/g, "/");
  let doc = `        """${title}.\n\n        ${verbPath}`;
  if (op.description) doc += `\n\n        ${oneLine(op.description).replace(/"""/g, "'''").replace(/\\/g, "/")}`;
  doc += '\n        """\n';
  return (
    `    def ${op.pyName}(${params.join(", ")}) -> ${returnType(op, ctx)}:\n` +
    doc +
    `        return self._http.${method}(${call.join(", ")})\n`
  );
}

/** client.py: one API class per tag plus the VegadutaClient facade. */
export function emitClient(model) {
  const ctx = { typeNames: model.typeNames, prefix: "m.", quoteRefs: false };
  let out = `${PY_BANNER}\nfrom __future__ import annotations\n\n`;
  out += "from typing import Any, Dict, Iterator, List, Literal, Optional, Union  # noqa: F401\n\n";
  out += "from . import models as m  # noqa: F401\n";
  out += "from ..runtime import DEFAULT_BASE_URL, HttpClient, quote_path  # noqa: F401\n\n\n";
  for (const g of model.groups) {
    out += `class ${g.className}:\n    def __init__(self, http: HttpClient) -> None:\n        self._http = http\n`;
    for (const op of g.operations) out += `\n${emitOperation(op, ctx)}`;
    out += "\n\n";
  }
  out += "class VegadutaClient:\n";
  out += '    """Entry point: one attribute per API group (controller)."""\n\n';
  out += "    def __init__(\n        self,\n        token: Optional[str] = None,\n        *,\n        base_url: str = DEFAULT_BASE_URL,\n";
  out += "        timeout: float = 60.0,\n        headers: Optional[Dict[str, str]] = None,\n    ) -> None:\n";
  out += "        self.http = HttpClient(base_url=base_url, token=token, timeout=timeout, headers=headers)\n";
  for (const g of model.groups) out += `        self.${g.pyAttr} = ${g.className}(self.http)\n`;
  out += "\n\nClient = VegadutaClient\n";
  return out;
}

/** generated/__init__.py: marks the directory as a package. */
export function emitPackageInit() {
  return `${PY_BANNER}"""Generated half of the SDK: models.py (TypedDicts) and client.py (one class per API group)."""\n`;
}
